const asset = '../../assets/one-shop/';
const stages = [
 { title:'사장님과 라미', subtitle:'주모 샵을 준비하고 있어요', expression:'hello', alt:'손을 들고 반갑게 인사하는 파란 캐릭터 라미', composer:'사장님이 알려주시면 함께 정리해요', content:`<div class="bubble">사장님, 반가워요!<br>메뉴판 사진부터 보여주시겠어요?</div><div class="menu-photo"><img src="${asset}onboarding/jumo-menu-photo.png" alt="예시로 등록한 주모 메뉴판 사진"><span><strong>주모 메뉴판.jpg</strong>메뉴판 사진을 올렸어요</span></div><div class="bubble">이렇게 정리했어요. 가격이 맞는지 확인해 주세요.<div class="mini-menu"><span>주모 시그니처 보쌈</span><b>32,000원</b><span>바삭 감자전</span><b>15,000원</b></div></div>`},
 { title:'사장님과 라미', subtitle:'샵 링크와 QR 예시', expression:'celebrate', alt:'샵 링크가 준비되어 기쁘게 축하하는 라미', composer:'확인한 내용으로 샵을 소개해요', content:`<div class="bubble user">메뉴와 가격이 맞아요!</div><div class="bubble">좋아요! 손님을 만날 샵 링크와 QR이 준비됐어요.</div><div class="qr-card"><img src="${asset}onboarding/integrated-qr-table-ko.svg" alt="프로덕션북 시연용 QR코드"><div><b>주모 · 6번 테이블</b><span>QR을 찍고 언어를 선택해요.</span><span>온라인에는 샵 링크를 공유해요.</span></div></div><div class="ticket-caption">프로덕션북에 연결되는 예시 QR입니다.</div>`},
 { title:'손님과 라미', subtitle:'Tiếng Việt · 베트남어 대화 예시', expression:'ordering', alt:'손님의 주문을 받는 라미', composer:'손님은 자기 언어로 이야기해요', content:`<div class="bubble">Chào bạn! Bạn muốn ăn món gì?<div class="translation">안녕하세요! 어떤 메뉴를 드시고 싶으세요?</div></div><div class="bubble user">Cho tôi một bánh khoai tây, không cay nhé.<div class="translation">감자전 하나 주세요. 맵지 않게 해주세요.</div></div><div class="bubble">Được rồi! Bạn ngồi ở bàn số mấy?<div class="translation">네! 몇 번 테이블에 계신가요?</div></div><div class="bubble user">Bàn số 6. <span lang="ko">6번 테이블이에요.</span></div>`},
 { title:'홀·주방·사장님', subtitle:'같은 주문을 한국어로 확인해요', expression:'happy', alt:'주문을 잘 전달하고 행복한 라미', composer:'샵이 준비 상황을 바꾸면 손님도 확인해요', content:`<div class="bubble">6번 테이블에서 주문이 들어왔어요.</div><div class="order-ticket"><div class="ticket-head"><strong>6번 테이블</strong><span>신규 주문 · 예시</span></div><div class="ticket-line"><b>바삭 감자전 × 1</b><b>15,000원</b></div><div>요청: 맵지 않게 해주세요.</div><div class="translation">원문: Không cay nhé.</div></div><div class="bubble user">접수했어요. 주방에서 준비할게요.</div><div class="bubble">손님에게도 알려드렸어요.<div class="translation">Quán đã nhận đơn và đang chuẩn bị món cho bạn.</div></div>`}
];
const controls=[...document.querySelectorAll('[data-step]')];
const conversation=document.querySelector('#conversation');
function showStage(index){const s=stages[index];document.querySelector('#stage-title').textContent=s.title;document.querySelector('#stage-subtitle').textContent=s.subtitle;document.querySelector('#composer-text').textContent=s.composer;const img=document.querySelector('#rami-face');img.src=`${asset}rami/expressions/${s.expression}.webp`;img.alt=s.alt;conversation.innerHTML=s.content;controls.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));}
controls.forEach((b,i)=>{b.addEventListener('click',()=>showStage(i));b.addEventListener('keydown',event=>{if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();const next=(i+(event.key==='ArrowRight'?1:-1)+controls.length)%controls.length;showStage(next);controls[next].focus();}})});
showStage(0);
const menuButton=document.querySelector('.menu-toggle');const navigation=document.querySelector('#navigation');function closeMenu(){menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','메뉴 열기');navigation.classList.remove('open');}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');navigation.classList.toggle('open',open);});navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});window.addEventListener('resize',()=>{if(window.innerWidth>700)closeMenu();});
